  function enrichAnaraut(entry) {
    const intro = entry.pages[0];
    const introduction = "<p>Anaraut Draig ist der Erbe von Celtigerns Wacht und dient als Adjutant des Marschalls. Sein Gefolge steht dort bereit, wo eine Meldung verl\xE4sslich gepr\xFCft, ein Schutzauftrag \xFCbernommen oder eine Entscheidung ohne unn\xF6tigen Aufschub ausgef\xFChrt werden muss.</p><p>Die Arbeit f\xFChrt zwischen Hof, Wegen und Dienststellen hindurch: Berichte aufnehmen, die Lage vor Ort kl\xE4ren, gef\xE4hrdete Menschen sch\xFCtzen und Auftr\xE4ge mit nachvollziehbarem Ergebnis zur\xFCckmelden. Rang und Familienname nehmen den Beteiligten diese Verantwortung nicht ab.</p><p>An Land verbinden F\xFChrung, Ritter und Knappen den bewaffneten Dienst mit der Ausbildung der J\xFCngeren. Zur See tr\xE4gt Arian Saethwyr das Kommando. Wo ihre Wege zusammenf\xFChren, m\xFCssen Auftrag und Zust\xE4ndigkeit ebenso klar sein wie der Kurs: Ein dringender Befehl vertr\xE4gt keine Ungewissheit dar\xFCber, wer ihn ausf\xFChrt.</p>";
    if (/^Erzählerischer Einstieg:/.test(intro.description || "") || !intro.description) intro.description = introduction;
    else intro.description += introduction;
    if ((intro.stats || []).every((row) => row[1] === "Wert")) intro.stats = [
      ["Anf\xFChrer", "Anaraut Draig"],
      ["Stellung", "Erbe von Celtigerns Wacht"],
      ["Dienst", "Adjutant des Marschalls"],
      ["Auftrag", "Verl\xE4ssliche Meldungen \xB7 Schutz \xB7 dringende Eins\xE4tze"],
      ["Zur See", "Arian Saethwyr \xB7 gesondertes Schiffskommando"]
    ];
    const hierarchy = entry.pages.find((page) => page.hierarchyPage)?.hierarchy;
    if (hierarchy) {
      const levels = [hierarchy.levels || [], ...(hierarchy.trees || []).map((tree) => tree.levels || [])];
      for (const list2 of levels) for (const level of list2) for (const node of level.nodes || []) {
        if (String(node.text || "").trim()) continue;
        const role2 = String(node.subtitle || "").toLocaleLowerCase("de");
        node.text = Object.entries(duties).find(([key]) => role2.includes(key))?.[1] || "Dieser Platz ist noch nicht besetzt. Zust\xE4ndigkeit und Ausbildung werden bei der tats\xE4chlichen Besetzung festgelegt.";
      }
      if (!hierarchy.description || hierarchy.description === "....") hierarchy.description = "Anarauts Landgefolge verbindet F\xFChrung, Ritter sowie Knappen und Pagen im Dienst f\xFCr Celtigerns Wacht. Erfahrung wird weitergegeben, Verantwortung nach Auftrag und Ausbildung getragen.";
      if (/Die Gilde ist/.test(hierarchy.chartIntro || "")) hierarchy.chartIntro = "Die Dienstordnung des Gefolges verbindet F\xFChrung, bewaffneten Schutz und Ausbildung. Leere Pl\xE4tze sind keine zus\xE4tzlichen Mitglieder.";
      if (/Gildensatzung/.test(hierarchy.footerNote || "")) hierarchy.footerNote = "Die Rangfolge des Landgefolges bleibt vom gesonderten Schiffskommando unber\xFChrt.";
    }
    const bio = entry.pages.find((page) => page.biographyPage);
    if (bio) {
      for (const row of bio.stats || []) {
        if (row[0] === "Vollst\xE4ndiger Name" && row[1] === "Anaraut Drag") row[1] = "Anaraut Draig";
        if (row[0] === "Titel" && row[1] === "Kronprinz, Ritter") row[1] = "Erbe von Celtigerns Wacht \xB7 Ritter";
      }
      if (/^Beschreibe Herkunft/.test(bio.description || "")) bio.description = "Anaraut Draig \xB7 Erbe von Celtigerns Wacht und Adjutant des Marschalls.";
      if (/^Beschreibe Herkunft/.test(bio.biography?.biographyText || "")) bio.biography.biographyText = "<p>Als Erbe von Celtigerns Wacht verbindet Anaraut seine Herkunft mit dem Dienst als Adjutant des Marschalls. Das Gefolge unterst\xFCtzt ihn bei Meldungen, Schutzauftr\xE4gen und der Ausf\xFChrung erteilter Befehle.</p>";
    }
    if (!entry.pages.some((page) => page.commentThreadKey === ARIAN_HIERARCHY_KEY)) {
      const landingIndex = entry.pages.findIndex((page) => page.landingPage);
      entry.pages.splice(landingIndex + 1, 0, buildArianShipHierarchy(hierarchy?.emblem || entry.symbol || ""));
    }
    return entry;
  }

  // modules/combat/combat-hit-point-progression.js
  var integer = (value, fallback = 0) => Number.isFinite(Number(value)) ? Math.trunc(Number(value)) : fallback;
  function getStandardHitPointProgression({ hitDie = 8, averagePerLevelOverride = null, level = 1, constitutionModifier = 0 } = {}) {
    const effectiveLevel = Math.max(1, Math.min(30, integer(level, 1)));
    const constitution = integer(constitutionModifier);
    const first = Math.max(1, hitDie + constitution);
    const gain = Math.max(1, (averagePerLevelOverride ?? Math.floor(hitDie / 2) + 1) + constitution);
    const base = first + (effectiveLevel - 1) * gain;
    const bonus = Math.ceil(base / 4);
    return {
      base,
      bonus,
      total: base + bonus,
      gain,
      vitalityGain: effectiveLevel === 1 ? bonus : bonus - Math.ceil((base - gain) / 4)
    };
  }

